	private static readonly CrucibleGuideBoard First=new CrucibleGuideBoard(0,"First Board",new int[10] { 47, 5, 31, 33, 13, 50, 1, 46, 25, 32 },new CrucibleGuideFight[6] {
		new CrucibleGuideFight("Bone Knight & Bone Bishop","Normal",new string[2] { "Bone Knight", "Bone Bishop" },new int[3] { 47, 5, 31 },new string[6] { "Two targets are up the whole fight, but it is easy to manage. The Bishop opens with Death Spiral: stand underneath him when it goes off.", "The Knight casts Ossify often (a damage-up buff on itself). Interrupt it with Soul Crush; it is not dangerous otherwise.", "After Death Spiral the Knight casts Tumulus: step away from him.", "Then the Bishop casts Black Eruption. Stay out and wait for at least the second explosion before going under him - from the third onward there is a small safe spot under the Bishop. If unsure, stay out until it is clearly safe.", "Later the Knight uses Forward Guard. Use Snarl and Challenge to move enemy focus so you or your beast is behind him and can deal damage; the guard drops after enough damage.", "By now both are likely dead. If not, the Bishop casts Ancient Aero (line AoE, cleansable Windburn DoT) and the mechanics just cycle." },new string[1] { "Interrupt" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Soulkin },
			Interrupts = new string[1] { "Ossify" },
			Why = "An interrupt (Ice Golem's Soul Crush), tankiness and Blunt damage.",
			Abilities = new string[6] { "Bone Knight - Ossify: interruptible damage-up buff", "Bone Knight - Tumulus: small circle AoE around the Knight", "Bone Knight - Forward Guard: Regen and Directional Parry buff, blocks all damage from the front", "Bone Bishop - Death Spiral: donut AoE centred on the Bishop", "Bone Bishop - Black Eruption: marching circle AoE that starts on the Bishop and expands in cardinal or intercardinal directions", "Bone Bishop - Ancient Aero: line AoE that leaves a cleansable Windburn DoT" }
		},
		new CrucibleGuideFight("Arch Demon Piece","Normal",new string[1] { "Arch Demon" },new int[3] { 33, 13, 50 },new string[4] { "It opens with Abyssal Charge and targets you: just move out of the line AoEs.", "Dismember: standing in the middle and stepping into one of the dangerous squares after it has gone off works well. The timing is deceptively tricky, so expect a few tries.", "Abyssal Transfixion: swords hang in the air and drop circles underneath - move away from them. It finishes with an axe that cleaves the front, so stand behind.", "The mechanics loop and start layering on top of each other, so burn it down quickly before it gets hectic." },Array.Empty<string>()) {
			Why = "Plenty of Lightning damage and bulkiness.",
			Abilities = new string[3] { "Abyssal Charge: spawns spears around the arena that shoot line AoEs at you", "Dismember: five line AoEs across the whole board, east to west or west to east, going off one at a time", "Abyssal Transfixion: spawns swords that drop circle AoEs under them, and an axe that cleaves in front of the Arch Demon" }
		},
		new CrucibleGuideFight("Piscodemon Piece","Normal",new string[1] { "Piscodemon" },new int[3] { 1, 46, 25 },new string[5] { "Gets hectic the longer it goes on, so kill it as fast as you can.", "It opens with Void Blizzard III: look at the north wall to see where the circles spawn and stand in a lane without one. The circles march south along their lanes; when one passes beside you, move into that lane.", "Then Clear Mind (damage-up buff) with Arcane Blast. Dispel the buff with something like Bloodcurdling Caw.", "Void Flare Star: just move away to reduce the damage. Then dodge Void Thunder III and Void Aero III.", "Another Clear Mind / Arcane Blast follows, then it loops with the mechanics layered over each other." },Array.Empty<string>()) {
			Why = "Plenty of damage, Slashing damage from Zu, and tankiness.",
			Abilities = new string[6] { "Void Blizzard III: exaflare / marching-style AoEs from the north", "Clear Mind: damage-up buff on itself (can be dispelled)", "Arcane Blast: unavoidable AoE", "Void Flare Star: spawns a fireball that deals proximity-based damage", "Void Thunder III: cross AoE under the player", "Void Aero III: donut AoE under the Piscodemon Piece" }
		},
		new CrucibleGuideFight("Banemite Piece","Normal",new string[1] { "Banemite" },new int[3] { 13, 32, 47 },new string[4] { "Bedrock Uplift: stand next to the first circle that appears in the centre and step into it when it goes off to avoid the following AoEs.", "Deadly Thrust only applies a cleansable poison.", "Venom Web: the centre explodes first, then the perimeter circles go off in the order they appeared. Leave the centre and stand by the first outer circle, on the side opposite the rotation; step back to the centre once it has gone off.", "After a while three Miteling Pieces spawn. They mostly cast Silkscreen, so dodge the lines. Then it loops." },new string[1] { "Cleanse" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Ashkin },
			Why = "A cleanse from Geshunpest, damage from Colibri, and extra Ice damage and tankiness from Ice Golem.",
			Abilities = new string[4] { "Banemite - Bedrock Uplift: expanding circle AoE", "Banemite - Deadly Thrust: melee hit that applies a cleansable poison", "Banemite - Venom Web: 'Shiva circle' AoE", "Miteling - Silkscreen: line AoE that applies Heavy" }
		},
		new CrucibleGuideFight("Ogre Piece","Elite",new string[1] { "Ogre" },new int[3] { 46, 32, 31 },new string[5] { "Similar to the last boss of Halatali. It opens by jumping to a wall and casting Scorching Smite: go to the side or behind.", "Allfire drops two big fire circles and spams circle AoEs - dodge them.", "It jumps to one fire circle and casts Smite again, but teleports to the other circle before the cone lands. Stand behind where it will appear on the other circle, not where it started.", "Burning Ward makes it invulnerable and Wisps / Great Wisps march to the centre. Kill them before they arrive; Gigantoad's Quelling Wave is ranged and deals bonus damage to them.", "After that it mostly loops. Fire Call's fireball drops a circle when touched, so run from it until it despawns. Straight Punch is used now and then." },Array.Empty<string>()) {
			BorrowKins = new BeastKin[1] { BeastKin.Wavekin },
			Why = "A lot of damage from Zu and Colibri, tankiness and Quelling Wave from Gigantoad.",
			Abilities = new string[5] { "Scorching Smite: frontal cone", "Allfire: two large fire circles on the ground plus many circle AoEs", "Burning Ward: goes invulnerable and spawns wisps around the edge that march to the centre, exploding on contact for damage and a vulnerability-up debuff", "Fire Call: fireball that moves toward you and blows up on contact (drops a circle AoE)", "Straight Punch: strong melee hit" }
		},
		new CrucibleGuideFight("Pas de Seul","Boss",new string[1] { "Pas de Seul" },new int[3] { 1, 50, 13 },new string[4] { "Blood Rain: if her hand is raised and glowing it is a circle AoE, so get out; otherwise it is a donut, so stay in.", "Void Aero II follows: stand behind or beside her as it casts. The wind orb it makes casts radial cones, so watch the ground and move to the safe spot.", "Cold Caress is a cleansable poison. Then she summons a Succubus Mage and two Succubus Knights - burn them fast; Behemoth's Meteor one-shots them.", "A while later Blood Sword heals her. Her last move is Beguiling Mist: Nightmare plus two tethered hearts that drift together and explode into a big AoE - keep away from them. Then she loops until dead." },new string[1] { "Cleanse" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Ashkin },
			Why = "Plenty of Piercing damage, a cleanse, and a large AoE (Meteor) for the adds.",
			Abilities = new string[9] { "Pas de Seul - Blood Rain: circle or donut AoE", "Pas de Seul - Void Aero II: untelegraphed line AoE that throws a wind orb which spawns radial cone AoEs", "Pas de Seul - Cold Caress: cleansable poison", "Pas de Seul - Summon: a Succubus Mage and two Succubus Knights", "Pas de Seul - Blood Sword: melee hit that heals her", "Pas de Seul - Beguiling Mist: applies Nightmare and spawns two tethered purple hearts that move toward each other and make a large AoE when they meet", "Succubus Mage - Fanaticism: cleansable damage-up buff", "Succubus Mage - Void Fire: large circle AoE", "Succubus Knight - Sweet Steel: frontal cone AoE" }
		}
	});
	private static readonly CrucibleGuideBoard Second=new CrucibleGuideBoard(1,"Second Board",new int[12] {
		46, 40, 33, 25, 23, 28, 29, 38, 31, 5,
		41, 1
	},new CrucibleGuideFight[6] {
		new CrucibleGuideFight("Manticore Piece","Normal",new string[1] { "Manticore" },new int[3] { 25, 46, 40 },new string[5] { "It uses Arm and Hammer right away: go to the side without the glowing arm. It repeats with the other side.", "Deadly Hold follows and cannot be dodged - let your pet tank it.", "Hammerleap: run away from the wall it is facing, as far as you can. Then Heads and Tails / Tails and Heads: read the cast and dodge to match.", "Charge and Hammer is the tricky one: remember which arm glowed, dodge the line charges, then stand on the side that was safe from the glowing arm. When it goes off, move to the side it just cleaved, since the other side is cleaved next.", "Then it simply repeats until dead." },Array.Empty<string>()) {
			Busters = new string[1] { "Deadly Hold" },
			Why = "Tankiness and Wind damage.",
			Abilities = new string[5] { "Arm and Hammer: cleaves one half of the room; the glowing arm shows which side", "Deadly Hold: strong, unavoidable melee hit", "Hammerleap: faces a wall and jumps to it with a large circle AoE", "Heads and Tails / Tails and Heads: cleaves in front then behind, or behind then in front", "Charge and Hammer: telegraphs line AoE charges plus an initial Arm and Hammer side, then cleaves that side followed straight away by the other" }
		},
		new CrucibleGuideFight("Taurus Piece","Elite",new string[1] { "Taurus" },new int[3] { 1, 25, 38 },new string[5] { "Four squares on the ground light up gradually as you stand on them and, fully lit, cleanse Doom. The fight opens with Mortal Ray, so stand on a square to cleanse it.", "Ruinous Ring then Ruinous Locus: dodge. Right after comes Ray of Ignorance - drop it as far into a corner as you can for room to work with. Another Mortal Ray comes with it; cleanse it the same way.", "Aetherial Fissure: check east and west for which sigils glow first and leave their paths; after they fire, leave the other sigils' paths.", "Four Ahriman appear in the corners with a gaze: look away. They apply Doom, cleanse it as before. They then become targetable - kill them.", "Ruinous Contraction (ring then locus) starts being used, then everything loops until dead." },Array.Empty<string>()) {
			Why = "Piercing damage from Cu Sith and a lot of bulk for tanking.",
			Abilities = new string[7] { "Mortal Ray: applies a Doom debuff lasting 25 seconds", "Ruinous Ring: donut AoE", "Ruinous Locus: circle AoE", "Ray of Ignorance: spawns an orb that pulses circle AoEs which grow as it casts", "Aetherial Fissure: spawns sigils that fire line AoEs across the arena", "Ruinous Contraction: donut AoE followed by a circle AoE", "Summons four Ahriman in the corners with gaze mechanics (apply Doom)" }
		},
		new CrucibleGuideFight("Wyvern Piece","Normal",new string[1] { "Wyvern" },new int[3] { 33, 25, 1 },new string[4] { "It opens with Storm's Grip. The sprites stay for the rest of the fight, so you dodge their lines on top of everything else.", "Typhoon: ride out the knockback then dodge the tornadoes as they cross. Liquid Hell: dodge, and remember where the puddles land because they stay and matter next.", "Blazing Trail: run behind the boss while avoiding the puddles. The sprites telegraph while you are still moving, but you can safely get behind the boss first, so do not stop halfway. It ends by returning to the centre for Storm Trail: dodge the cones.", "Then Liquid Hell again and another Typhoon - the tornadoes are bigger the second time, so give more room. Blazing Trail is handled the same, then it loops." },Array.Empty<string>()) {
			Why = "Good Lightning damage and bulk from Adamantoise and Cu Sith.",
			Abilities = new string[5] { "Storm's Grip: spawns wind sprites in the northwest and southeast that periodically fire line AoEs across the north and south of the arena", "Typhoon: knockback, and tornadoes spawn on the edge and cross to the opposite side, hurting on touch", "Liquid Hell: fire puddles on the ground that apply Burns when walked through", "Blazing Trail: jumps to the east or west wall and fires a wide line AoE", "Storm Trail: three cone AoEs marked by glowing green sigils around the boss" }
		},
		new CrucibleGuideFight("Voidmancer Piece","Normal",new string[1] { "Voidmancer" },new int[3] { 1, 23, 28 },new string[3] { "It opens with Death Drive. Drop it where it catches the fewest Zombie Pieces - the northeast and southwest wall spots only reach one. The zombies are not a big problem either way; kill whatever comes up (Golem and Worm have the area damage). Do not let them chew on you, since Wit's End turns into Confusion at 12 stacks.", "Then Dark Orb, then Evil Mist: dodge.", "Death Drive and Dark Orb repeat, handled the same. It finishes the sequence with Mindjack into Evil Mist: get into position before the debuff expires so the forced run does not take you into the orbs. Then it loops." },Array.Empty<string>()) {
			Why = "Generally good damage, Earth damage, and AoE to deal with the Zombie Pieces.",
			Abilities = new string[5] { "Death Drive: large AoE under the player that resurrects any Zombie Pieces in the area", "Dark Orb: massive circle AoE", "Evil Mist: spawns orbs that pulse circle AoEs", "Mindjack: applies a Force March debuff that makes you run in the shown direction when it expires", "Zombie Pieces: their auto-attacks apply Wit's End, which becomes Confusion at 12 stacks" }
		},
		new CrucibleGuideFight("Tablitaur Pieces","Elite",new string[1] { "Tablitaur" },new int[3] { 29, 38, 23 },new string[4] { "Two targets the whole time and, unlike the Bone Knight and Bishop, not easy. Both hit hard, do not use abilities in a fixed order, and cast at the same time, so watch both cast bars to see which resolves first.", "1000-tonze Swipe: stand behind whichever finishes first, then swap sides when it goes off. 1111-tonze Swing is the reverse: stand near the one casting it second, as far from the first as possible, then swap once the first has gone off.", "10-tonze Stomp: position so you are not knocked into a wall, and try not to have you and your beast both take it. 100-tonze Slash is simple. Interrupt Rallying Cheer with Soul Crush.", "Endless Swing and Endless Swipes are the hard part: keep running from the spinner while avoiding the other one's cones. Expect a few tries before it clicks. Then it loops until both are dead." },new string[1] { "Interrupt" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Soulkin },
			Interrupts = new string[1] { "Rallying Cheer" },
			Why = "Plenty of damage (Fire from Spriggan), bulk, and two sources of Soul Crush to interrupt Rallying Cheer.",
			Abilities = new string[7] { "1000-tonze Swipe: half-room cleave in the direction the enemy faces", "1111-tonze Swing: massive circle AoE around the enemy", "10-tonze Stomp: knockback from a blue circle on the ground", "100-tonze Slash: strong line AoE", "Rallying Cheer: interruptible cast that gives a dispellable damage-up buff", "Endless Swing: starts in a corner and slowly moves toward you, constantly spinning and hurting on touch", "Endless Swipes: jumps to the centre and spams rotating cone attacks" }
		},
		new CrucibleGuideFight("Loosefroxy Inkyjots & Chewchum Popoto","Boss",new string[2] { "Loosefroxy", "Chewchum" },new int[3] { 41, 31, 5 },new string[6] { "Another multi-target fight. Kill both at around the same time to avoid an endless enrage, but Chewchum Popoto is not always targetable.", "The worm starts burrowed, moves to a sandpool marked with a '!' and casts Sand Breath: go to that pool and stand behind it. Loosefroxy then uses Gobspin Headlops: a long glowing sword means stay close, a short non-glowing one means get away. Kinborrow comes next and can be dispelled with Quelling Wave.", "Gobbieboom Barrage spawns four round bombs in the centre. The worm dashes three times between pools; when it stops, hit a bomb so it is pushed into that pool. It detonates and knocks the worm onto its back - use all your burst on the worm then. Sidestep Bomb Toss meanwhile.", "The worm does three dashes and a Sand Breath while Loosefroxy drops four spiky bombs and casts Gobspin Headlops again: avoid the cross AoEs and the headlops. Kinborrow again (dispel it), then Goblin Hammer, which leaves very small safe spots.", "The next barrage has both spiky and round bombs. Follow the worm to see which pool it ends in. The large bombs go off first, but the centre of the arena has a safe space. Push a small bomb into the worm's pool while avoiding the spiky bomb AoEs, then burst the worm again.", "From here the mechanics repeat, sometimes layered, until both are dead." },new string[1] { "Dispel" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Wavekin },
			Dispels = new string[1] { "Kinborrow" },
			Why = "Quelling Wave for Water damage and dispel, Blunt damage, and quite a bit of tankiness.",
			Abilities = new string[7] { "Loosefroxy - Gobspin Headlops: circle or donut AoE (sword raised and not glowing = circle, glowing = donut)", "Loosefroxy - Kinborrow: dispellable vulnerability-down debuff", "Loosefroxy - Gobbieboom Barrage: waves of Gobbie Bombs; small round bombs can be pushed and have a small circle AoE, large spiky bombs cannot be pushed and have a large cross AoE", "Loosefroxy - Bomb Toss: small circle AoE", "Loosefroxy - Goblin Hammer: many medium circle AoEs all over the arena", "Chewchum Popoto - Sand Breath: frontal cone AoE", "Chewchum Popoto - Earthquake: enrage AoE" }
		}
	});
	private static readonly CrucibleGuideBoard Third=new CrucibleGuideBoard(2,"Third Board",new int[14] {
