	},new CrucibleGuideFight[8] {
		new CrucibleGuideFight("Cavalier Piece","Normal",new string[1] { "Cavalier" },new int[3] { 34, 2, 50 },new string[4] { "It opens with two Bone Bishops: kill them while avoiding Steelripper.", "Doubling spawns two clones that use Menace - move to a safe corner.", "Crushing Blade: position so you are not knocked out of the arena.", "Two more Bone Bishops come a bit later and Meteor makes quick work of them. The clones then spawn on a wall and cast Valfodr. By now the boss should be almost dead; otherwise it loops." },Array.Empty<string>()) {
			Why = "A ton of damage, good AoE for the adds, and a lot of Fire damage.",
			Abilities = new string[6] { "Steelripper: frontal cone", "Doubling: absorbs up to five orbs to create clones", "Menace: large circle AoE from each clone", "Crushing Blade: knockback and high damage; cannot be stopped with pet cover", "Valfodr: line AoE across the whole arena from each clone", "Summons Bone Bishops as adds" }
		},
		new CrucibleGuideFight("Ymir Piece & Sahagin Piece","Normal",new string[2] { "Ymir", "Sahagin" },new int[3] { 26, 8, 47 },new string[5] { "Spawn Ice Golem first to get Soul Crush, then switch to Buffalo.", "Attack the Ymir's shell, but do not attack the Sahagin while Paralyzing Spikes is up. Interrupt Blanket Thunder with War Cry.", "After the Tsunami knockback the Sahagin casts Dreadwash: make sure to interrupt it.", "Once the Ymir is out of its shell, use Parting Blow and swap to Diremite. Silkscreen roots it so you can finish it, then finish the Sahagin.", "Alternatives: burn the Sahagin before it puts up spikes, or use Quelling Wave on it, since that does not reflect the paralysis and your pet ignores the spikes. With the Sahagin dead the Ymir is easy." },new string[1] { "Interrupt" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Soulkin },
			Interrupts = new string[1] { "Dreadwash" },
			OpenWith = BeastKin.Soulkin,
			Why = "Buffalo, Diremite and Ice Golem: Soul Crush from Ice Golem, War Cry and Parting Blow from Buffalo, and Silkscreen (root) from Diremite.",
			Abilities = new string[5] { "Sahagin - Paralyzing Spikes: buff that paralyses whoever hits it; cast at the start and each time the Ymir gets a new shell; cannot be dispelled", "Water II: several baited AoEs", "Blanket Thunder: raidwide damage (interruptible with War Cry)", "Tsunami: knockback from a wall covering about 90% of the arena; cannot be stopped with pet cover", "Sahagin - Dreadwash: interruptible cast that applies Hysteria" }
		},
		new CrucibleGuideFight("Catoblepas Piece","Normal",new string[1] { "Catoblepas" },new int[3] { 32, 44, 10 },new string[3] { "Bestial Roar is nearly the only mechanic. See which orb or ring is about to hit the wall and move accordingly: small orbs become large circle AoEs at the wall, the multi-ring shape becomes a donut. A shape you hit early pops early, so you may hit the donut ones early if that helps.", "With Shifting Gaze up, handle the orbs the same way, but look away from those showing the eye telegraph as they resolve.", "Jettataura: step out of the puddle. Otherwise the mechanics loop until it is dead." },Array.Empty<string>()) {
			Why = "Nothing specific is needed - bring a ton of damage.",
			Abilities = new string[3] { "Bestial Roar: spawns three orbs and three rings that travel outward and explode on reaching a wall or on touching you. Orbs are very large circle AoEs, rings are donuts. Being hit petrifies", "Shifting Gaze: from the second Bestial Roar on; three pairs of one orb and one ring, one of each pair tethered by the boss; the tethered one with an eye petrifies if looked at", "Jettataura: AoE under you that causes Hysteria" }
		},
		new CrucibleGuideFight("Zu Piece","Elite",new string[1] { "Zu Piece" },new int[3] { 47, 44, 10 },new string[2] { "The whole fight is about the eggs. Killing one gives the Zu a permanent damage buff, and they break to any AoE dropped on them. The adds from Hatch are different: killing them gives no buff and they have little health. Two eggs hatch - kill the two adds, and interrupt Caustic Vomit if needed.", "Keep your AoEs off the eggs. Drop Crossbreeze in the middle and move out once it locks in. Do not drop Flying Frenzy on your pet. Stretch the Fore/Rear Carve tethers until they turn purple to minimise damage. For Airy Pursuit, drop it at a wall and run straight across to the other wall." },new string[1] { "Interrupt" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Soulkin },
			Busters = new string[1] { "Flying Frenzy" },
			Interrupts = new string[1] { "Caustic Vomit" },
			Why = "Your highest damage beasts and an interrupt.",
			Abilities = new string[6] { "Hatch: two eggs hatch if they are not killed before the cast bar ends", "Caustic Vomit: interruptible damage-buff cast by the add", "Crossbreeze: plus-shaped AoE", "Flying Frenzy: AoE tank buster", "Ferocious Fore Carve / Rear Carve: tether that cleaves in front or behind; does not break eggs", "Airy Pursuit: AoEs that follow you" }
		},
		new CrucibleGuideFight("Lakhamu Piece","Normal",new string[1] { "Lakhamu" },new int[3] { 26, 15, 50 },new string[3] { "It opens with Landslip, pushing you about two golems' worth of distance. Position so that no golem is looking straight at you after the knockback.", "The golems come alive: stun them with War Cry and finish them with Parting Blow. Then swap to Crab and burn her down with its Water damage.", "Do not stack with your pet for Earth Shaker. For Earthrender step out of the three puddles under you; for Sand Tempest move to a space with no orbs. Then it repeats until dead." },Array.Empty<string>()) {
			Why = "Buffalo, Crab and Behemoth: War Cry and Parting Blow for the golems, Water damage from Crab.",
			Abilities = new string[4] { "Landslip: spawns golems and knockback lines that move you about half the room (cannot be stopped with pet cover); the golems shoot lines and then become adds", "Sand Tempest: blind plus orbs that explode as circle AoEs; the blind cannot be cleansed", "Earth Shaker: cones on you and your pet", "Earthrender: three baited AoEs" }
		},
		new CrucibleGuideFight("Cactuar Pieces","Random",new string[1] { "Cactuar" },new int[3] { 50, 26, 25 },new string[3] { "Use Meteor to kill the adds that spawn first.", "War Cry is good on wave two once they are grouped, then finish with Shield Charge.", "Adamantoise gives very good tankiness and Lightning damage. Finish the last set of adds with Shield Charge, then kill the large enemies - Guardia first, then Campeador." },Array.Empty<string>()) {
			Why = "Good AoE, tankiness and damage.",
			Abilities = new string[7] { "Emergency Order: the boss jumps away and starts spawning waves", "Healing Water: Flowertenders constantly AoE-heal the Sabotenders", "??? Needles: circle AoEs that go off in the order of their numbers", "Cover: the Guardia takes all damage in place of the Campeador", "Seedling Needles: raidwide with the boss on the ground, donut with the boss in the air", "Needle Gnarl: circle AoE", "Wave 1: two Flowertenders and Sabotenders. Wave 2: four Soldado and Sabotenders. Wave 3: Guardia, Campeador and Sabotenders" }
		},
		new CrucibleGuideFight("Siren Piece","Elite",new string[1] { "Siren" },new int[3] { 50, 32, 1 },new string[4] { "Keep a Shield Charge on hand: gap closing is valuable here.", "She opens with Song of Torment: tank it or have your pet tank it. When she casts Unmooring Melody run to her and stand at her side straight away - it is a FAST cast. For Feral Lunge stay out of her path.", "Kill the adds from the first Summon with Meteor. Dead Man's Dirge follows: read her wings and dodge.", "Inviting Verse resolves right after an Unmooring Melody: position so you run back toward the centre afterwards; the debuff shows which direction you will run." },Array.Empty<string>()) {
			Busters = new string[1] { "Song of Torment" },
			Why = "AoE for the adds and a lot of Piercing damage for the boss.",
			Abilities = new string[7] { "Song of Torment: tank buster", "Unmooring Melody: untelegraphed fast cast; jumps to a random wall and channels a cone that applies a stacking debuff, confusing at 16 stacks", "Feral Lunge: jumps to a random wall, then a line AoE", "Summon: three normal zombies and one tethered to you; the tethered one binds you on contact", "Dead Man's Dirge: donut with her wings spread, circle with wings together", "Distant Tune: three sets of orbs that explode as circle AoEs", "Inviting Verse: forced march, paired with an Unmooring Melody but only happens once she stops singing" }
		},
		new CrucibleGuideFight("Guttler Piece","Boss",new string[1] { "Guttler" },new int[3] { 25, 32, 1 },new string[4] { "Her auto-attacks are cones, so do not stand near your pet. The side statues wake if hit by AoEs (mainly the line attacks), so aim line attacks away from them; if they do wake, kill the adds. She follows a loose timeline but not always in the same order, so read each mechanic as it happens.", "Gyrocleave: stand in the cubbies at the side of the arena. Beastly Aura: stand next to her to be knocked straight into a cubby. Gluttonous Goring wants you in the cubby on the opposite side (move early, Sprint helps); Gluttonous Gutting is the reverse - stand behind, in the cubby the boss is in.", "Thunderbolt: do not hit both yourself and your pet. Overpowering Point: leave once the AoEs lock in. Thunderbolt paralyses, so use a serum or other resistance; use it at the start of the fight, there is plenty of time to win. Molten Metal: drop it in one of the far cubbies, then move to the other side.", "Then the mechanics loop until dead." },Array.Empty<string>()) {
			Busters = new string[1] { "Thunderbolt" },
			Why = "No special beast needs - a mix of tankiness and high damage. Bring paralysis resistance (Crimson Ribbon or a G2 Antiparalysis Soul Serum).",
			Abilities = new string[8] { "Gyrocleave: vertical line AoE", "Beastly Aura: knockback north and south of the boss", "Gluttonous Goring: jumps to a side and floats with the axe hanging below; swords spawn with circle AoEs and the boss does a massive circle AoE", "Gluttonous Gutting: jumps to a side and holds the axe behind; swords spawn with circle AoEs, then a frontal cleave", "Thunderbolt: line tank buster that paralyses", "Overpowering Point: baited line AoE", "Deadly Demesne: cages and floating daggers; cages detonate their tile and the four adjacent tiles, daggers hit the tile the blades point along; cages bind you if you stand in one", "Molten Metal: baited AoE that leaves a sword which explodes in a proximity AoE" }
		}
