	},new CrucibleGuideFight[10] {
		new CrucibleGuideFight("Strix Piece","Normal",new string[1] { "Strix" },new int[3] { 16, 44, 10 },new string[4] { "Plummet: stand out of the first row and move in after it goes off.", "Quakes: be in the levitation circle when it goes off. Floods: turn into a kappa. Magical Mallet Theory: step into the slime puddle to become a slime.", "Ultimate Focus into On the Properties of Darkness can be dispelled, but it does not hit hard either way.", "After Windfeather Whisper knocks you back, gap close with Shield Charge. Check Out: note which books have their mouths open, move away from them, and rotate as they go off. Then it repeats until dead." },Array.Empty<string>()) {
			Why = "Mostly high-DPS beasts, to skip as much of the fight as possible.",
			Abilities = new string[8] { "Plummet: three rows of three AoEs", "On the Properties of Quakes: answered by standing in the levitation circle", "Magical Mallet Theory: turns you into a slime (stunned while transformed, but only 1 damage)", "On the Properties of Floods: damage and knockback unless you are a kappa", "Ultimate Focus: dispellable magic damage buff", "On the Properties of Darkness: raidwide damage", "Windfeather Whisper: summons a feather add with an unavoidable knockback", "Check Out: summons books that do pairs of circle AoEs in the order their mouths open" }
		},
		new CrucibleGuideFight("Morbol Piece","Normal",new string[1] { "Morbol" },new int[3] { 50, 28, 13 },new string[3] { "The main plan is to burn the boss down as soon as possible and ignore mechanics. Spawn Geshunpest first to borrow Scouring Ash, then switch to Behemoth.", "Never stand in front of the boss, and use Meteor to dispatch the adds.", "Use Scouring Ash if you get any debuffs, and Parting Blow to kill later adds before switching to Worm. Otherwise avoid the AoEs and burn the boss." },new string[1] { "Cleanse" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Ashkin },
			OpenWith = BeastKin.Ashkin,
			Why = "Strong AoE damage and a safety cleanse.",
			Abilities = new string[6] { "Extremely Bad Breath: rotating cones that apply paralysis, blind and heavy (all cleansable)", "Tremblor: knockback from the boss", "Vine Probe: line AoE in front", "Seedlings (add): poison on auto-attack, cleansable", "Carrion (add): slow, heavy-hitting autos; applies vulnerability, heavy and paralysis in melee range (paralysis is cleansable)", "Ochu (add): casts Acid Mist, a circle AoE that leaves a toxic puddle" }
		},
		new CrucibleGuideFight("Corpse Flower Piece","Random",new string[1] { "Corpse Flower" },new int[3] { 16, 44, 10 },new string[3] { "Stand in the thorns to prevent the Floral Trap draw-in, and do not stand in front after the pull or it may still eat you. Take Rotten Stench alone if you want your pet to avoid the damage.", "Floral Trap eats the Queen Hawk and kills it instantly with no damage buff, so for later traps position so you are not pulled in but the Queen Hawk is.", "Acid Rain: keep moving. Then it repeats until dead." },Array.Empty<string>()) {
			Why = "High-DPS beasts to burn it down and avoid mechanics. There is a good chance it is only a loot node.",
			Abilities = new string[5] { "Budding Thorns: summons three saplings with expanding thorns that slow you but stop draw-in effects while you are inside", "Floral Trap: binds you for two seconds then draws you in; if it lands the boss eats you and gains a damage buff", "Rotten Stench: stack marker", "Queen Hawk (add): casts Final Sting if it is not killed in time", "Acid Rain: AoEs that follow you" }
		},
		new CrucibleGuideFight("Ice Dragon Piece","Random",new string[1] { "Ice Dragon" },new int[3] { 16, 44, 13 },new string[3] { "Icy Torment: if the icicles are on the sides stand on top of the boss; if there are none avoid the centre and stay at the boss's sides. Rime Wreath: get away to avoid the damage.", "Withering Eternity is tough: move to the safe cubby, then avoid Sheet of Ice. The AoEs drop much slower than you expect, so do not panic and drop them in place.", "Cauterize: watch where the dragon telegraphs the lines and dodge; finish positioned so the knockback does not send you into the wall, and kill the ice sprites during it. Then it loops." },new string[1] { "Cleanse" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Ashkin },
			Why = "Really high DPS beasts, plus Geshunpest to borrow Scouring Ash at the start in case of Frostbite.",
			Abilities = new string[4] { "Icy Torment: floating icicles cleave the sides (middle safe); ice sucking in cleaves the middle (sides safe)", "Rime Wreath: circle AoE that applies a cleansable DoT", "Withering Eternity: AoE DoTs covering the arena with two safe spots on the cardinals; follows with Sheet of Ice, six baited AoEs", "Cauterize: stores four half-arena cleaves, ending with a knockback" }
		},
		new CrucibleGuideFight("Gargoyle Piece","Elite",new string[1] { "Gargoyle" },new int[3] { 7, 50, 13 },new string[3] { "Rippling Evisceration: stay out, then move in. Sweeping Evisceration: stretch the tether until it is purple to minimise damage, then move behind, then in front.", "Malady spawns many orbs: take up to four at a time and wait for the debuff to time out before more, soaking them 4-4-2 to clear them all.", "Sweeping Evisceration follows right after Malady, then it moves to the centre for Fivefold Fallout. Desolation: leave the front. Grim Fate can be tanked by your pet or by you. Sea of Pitch: kite around the boss and stay out of the puddles. Then it repeats." },Array.Empty<string>()) {
			Busters = new string[1] { "Grim Fate" },
			Why = "Not much beast-specific here - tankiness and damage.",
			Abilities = new string[7] { "Rippling Evisceration: circle AoE then a donut", "Sweeping Evisceration: tether; the boss dashes to you and cleaves in front, then behind", "Malady: spawns orbs that give the boss a damage buff; standing on an orb pops it and gives stacks that cause Hysteria at five", "Fivefold Fallout: four raidwides ending in a knockback (pet cover can stop it)", "Desolation: two casts of line AoEs in front", "Grim Fate: multi-hit tank buster", "Sea of Pitch: three baited lingering AoEs that inflict Hysteria if you stand in them" }
		},
		new CrucibleGuideFight("Administrator Piece","Random",new string[1] { "Administrator" },new int[3] { 25, 29, 13 },new string[2] { "Start with Spriggan to get Soul Crush. Dodge Flamethrower and interrupt Confound, then handle adds as they spawn: kill the Bug, avoid the Drone AoEs, and so on.", "This boss dies FAST, so you can even bring the Mantis, Damselfly and Wespe damage combo and burn it before much happens." },new string[2] { "Interrupt", "Cleanse" }) {
			BorrowKins = new BeastKin[2] {
				BeastKin.Soulkin,
				BeastKin.Ashkin
			},
			Interrupts = new string[1] { "Confound" },
			OpenWith = BeastKin.Soulkin,
			Why = "Tankiness and utility (Spriggan's Soul Crush, Geshunpest's cleanse), with Lightning damage as a bonus.",
			Abilities = new string[7] { "Flamethrower: frontal cone", "Confound: interruptible confusion debuff", "Bug (add): slowly walks to the orb; if not killed in time the boss casts Object 199 for a damage and regen buff", "Drone (add): baited line AoEs", "Footman (add): follows you with decent autos and periodically casts a circle AoE", "Cobra (add): casts Noxious Nova, a poison (cleansable, but each cast is a separate stack)", "Dreadnaught (add): frontal cone" }
		},
		new CrucibleGuideFight("Golem Piece","Elite",new string[1] { "Golem Piece" },new int[3] { 31, 16, 44 },new string[3] { "There are two golems to kill and a separate enrage after both die. They swap positions by tethering from one to the other, and the next attack then comes from the tethered golem. The order varies, so watch the cast bars.", "Earthen Ring: stay close. Plaincracker: get WAY away. Rock Wall: if the spikes face the middle get out, if they face outward get in. Stoneshower: stand under the cracked rocks. Outcrop: stand behind or to the side; after Obliterate gap close, or have your pet take it with Snarl.", "After both golems die a golem heart becomes targetable: kill it before Self-destruct finishes." },Array.Empty<string>()) {
			Why = "Mostly damage; Gigantoad adds Water damage and tankiness.",
			Abilities = new string[7] { "Earthen Ring: donut (a tether comes from the other golem)", "Plaincracker: large circle AoE (a tether comes from the other golem)", "Rock Wall: spawns walls with spikes; the spike side is hit once all walls spawn, and stuns", "Stoneshower: six floating rocks; normal rocks are circle AoEs, glowing rocks shatter into donuts", "Outcrop: frontal cone", "Obliterate: knockback (pet cover can stop it)", "Self-destruct: enrage" }
		},
		new CrucibleGuideFight("Treant Piece","Normal",new string[1] { "Treant" },new int[3] { 50, 28, 29 },new string[3] { "Start with Spriggan for Soul Crush, then swap to Behemoth. Several add waves spawn and the boss itself does little. Rustling Breeze: stand in front or at the sides depending on the telegraph.", "Kill the first Falling Leaves wave with Meteor. The second add wants burning down quickly; if you struggle bring something like Diremite to push it away for more time. For Arboreal Storm, wait for the first cast to go off then stand just outside the boss's sand puddle.", "The third add is the Biloko: have your pet Snarl for Acorn Bomb, interrupt Natural Nurture and focus the Biloko down. Otherwise just burn the adds as they come." },new string[1] { "Interrupt" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Soulkin },
			Interrupts = new string[1] { "Natural Nurture" },
			OpenWith = BeastKin.Soulkin,
			Why = "Plenty of AoE and an interrupt.",
			Abilities = new string[8] { "Rustling Breeze: glowing hands = side cones with the middle safe; glowing face = frontal cone with the sides safe", "Falling Leaves: summons adds", "Arboreal Storm: circle AoE that expands into donuts, knocking you up if it hits", "Acorn Bomb: spread AoE that applies sleep", "Slugs (add): cast baited AoEs", "Sapling (add): continuously gains regen and damage stacks and scales very high", "Biloko (add): casts Natural Nurture, healing the Treant for about 5% of its max health", "Diremite (add): line AoEs in front" }
		},
		new CrucibleGuideFight("Progenitrix Piece","Random",new string[1] { "Progenitrix" },new int[3] { 16, 44, 29 },new string[3] { "It jumps to a side and uses Scalding Scolding: move to its side. Adds then spawn - kill them ASAP but be mindful of the AoEs when they die.", "Kill the Grenade before it reaches 16 stacks or you will die.", "Pyrobolus: avoid the cones. It is not too bad and everything repeats until it is dead." },Array.Empty<string>()) {
			Busters = new string[1] { "Meltdown" },
			Why = "Nothing specific - just damage.",
			Abilities = new string[8] { "Scalding Scolding: jumps to a side and cleaves in front", "Meltdown: marker; line tank buster that binds, then knocks back, leaving three fire puddles along the path", "Fiery Fury: three knockbacks from purple circles; cannot be stopped", "Massive Explosion: interruptible raidwide", "Bomb (add): leaves fire puddles when killed", "Grenade (add): the boss is immune while it lives; constantly casts raidwides and gains a growing damage buff each time it is hit", "Snoll (add): explodes in a circle AoE when it dies", "Pyrobolus: several cone AoEs in all directions" }
		},
		new CrucibleGuideFight("Borgny Piece","Boss",new string[1] { "Borgny" },new int[3] { 7, 8, 35 },new string[4] { "Toxic Breath: go to the wall behind Borgny and stand at the sides when it jumps.", "Toxic Vomit: with poison resistance you can stand still; otherwise use Vulcanize or Smoldering Scales to reduce the damage, or have your pet tank it. Try to drop the puddles on the wall.", "Avoid the Fuming Vomit puddles and the poison clouds. Toxic Breath comes again - avoid as before. Wriggling Phlegm: drop it away from the Toxic Vomit puddles. Use Diremite's Silkscreen to root the ooze and burn it down; if it reaches a slime pool it explodes for damage and a damage-down on you.", "Watch for Cauterize while the boss is in the air. Salivous Snap can be tanked by you or your pet. Then burn the boss down as it repeats." },Array.Empty<string>()) {
			Busters = new string[1] { "Salivous Snap" },
			Why = "Coblyn, Diremite and Drake. With poison resistance you can bring more DPS instead of Coblyn and Drake.",
			Abilities = new string[6] { "Toxic Breath: backsteps then fires a lingering cone that applies poison", "Toxic Vomit: four baited puddles", "Fuming Vomit: AoEs that spread into eight moving clouds that slightly knock back", "Wriggling Phlegm: baited AoE that spawns a slime which moves to the nearest puddle and explodes on touching one", "Cauterize: flies to a side and does a line divebomb that spawns moving clouds like Fuming Vomit, ending with a knockback from the middle", "Salivous Snap: tank buster" }
		}
