	},new CrucibleGuideFight[14] {
		new CrucibleGuideFight("Flauros Piece","Normal",new string[1] { "Flauros" },new int[3] { 23, 28, 40 },new string[4] { "Spawn Ghost first to get Scouring Ash in case you end up paralysed, then summon Golem. The Golem can tank most of the fight, tank busters included.", "It opens with Heat Lightning: kill the sprites or dodge the lines. Charged Lightning: move behind.", "Later comes Erratic Blaster. If it hits you and you are paralysed, cleanse with the borrowed ability. If it hits the Golem, switch to Worm and let it tank the rest of the fight.", "Electric Shock: move away, then back in after it goes off. Then it repeats until dead." },new string[1] { "Cleanse" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Ashkin },
			Busters = new string[1] { "Erratic Blaster" },
			OpenWith = BeastKin.Ashkin,
			Why = "A lot of tankiness, Earth damage, and a cleanse.",
			Abilities = new string[5] { "Heat Lightning: summons three sprites that cast line AoEs (low health, can be ignored)", "Charged Lightning: frontal half cleave", "Electric Shock: large circle AoE", "Aetherial Offering: enlarges any sprites still alive, making their lines bigger", "Erratic Blaster: tank buster with paralysis (cleansable)" }
		},
		new CrucibleGuideFight("Mindflayer Piece","Elite",new string[1] { "Mindflayer" },new int[3] { 50, 28, 32 },new string[3] { "Kill the Myconids standing in the Void Water III puddles to prevent the AoE poison. Void Thunder III: make sure you are not in a water puddle when it goes off, then dodge the cross.", "It returns to the centre for Arcane Utterance. Worm's Bottomless Desert (Heavy) buys time, as the Mindflayer takes longer to return. Note which orbs Arcane Enhancement tethers and dodge their much larger lines.", "Void Paralysis III: have your pet tank it, then swap it out for the next one. Void Flare Stare: move to a corner opposite the flare star. Then it repeats until dead." },Array.Empty<string>()) {
			Busters = new string[1] { "Void Thunder III" },
			Why = "Solid AoE damage and burst damage to finish the Mindflayer.",
			Abilities = new string[7] { "Void Water III: spreads that drop puddles; standing in one lowers your lightning resistance", "Void Thunder III: AoE tank buster that explodes in a cross in the shape it leaves", "Arcane Utterance: summons four orbs that shoot lines in the directions of their arrows", "Arcane Enhancement: tethers orbs so they become larger and shoot larger lines", "Void Paralysis III: raidwide plus paralysis (cleansable)", "Void Flare Stare: proximity AoE", "Myconid (add): leaves spore zones when it dies; standing in one poisons you (cleansable)" }
		},
		new CrucibleGuideFight("Boogeyman Piece","Random",new string[1] { "Boogeyman" },new int[3] { 50, 28, 13 },new string[3] { "Spawn Geshunpest first for Scouring Ash, then switch to Behemoth. The boss has two weapons and its attacks depend on which it holds; its autos inflict a vulnerability of the opposite weapon. Whenever it swaps weapons with Provision, swap tanking between yourself and your beast.", "Swoop: stay out of the front and see where it jumps - with the sword follow it and stand at the side, with the club move away. Swing Round: sword - move away; club - stay close and be knocked back so you do not hit the wall (Shield Charge helps).", "Veil of Darkness: note where the invisible adds are. Meteor takes out many at once; bombs first, then the deepeye. Aim a dying sprite's cone toward the boss to reveal it - a good time is when the boss jumps on you. Ripples of Gloom just needs the blind cleansed. Then it loops." },new string[1] { "Cleanse" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Ashkin },
			OpenWith = BeastKin.Ashkin,
			Why = "AoE damage, tankiness and a safety cleanse.",
			Abilities = new string[10] { "Provision: swaps to the other weapon", "Ripples of Gloom: cleansable blind", "Veil of Darkness: boss goes invisible and summons bombs and a deepeye (they are invisible unless you are close); light sprites spawn later and stay visible", "Swoop (sword): dashes to the wall and casts a large cone toward the centre", "Swing Round (sword): large circle AoE", "Swoop (club): dashes to the wall and casts a massive circle AoE that knocks back", "Swing Round (club): large knockback", "Bomb (add): repeatedly casts Explosion, self-destructs if not killed", "Deepeye (add): gaze that petrifies if looked at", "Sprite (add): casts a cone toward where it faces when it dies" }
		},
		new CrucibleGuideFight("Atomos Piece","Random",new string[1] { "Atomos" },new int[3] { 50, 28, 25 },new string[2] { "Kill the gremlins with Meteor and Parting Blow. Kill the Bavarois before the Pudding spawns, and position so you are not knocked out of the arena.", "Stand in a puddle to reduce Pudding's damage, but out of them for Flan. Otherwise avoid the AoEs and keep killing the boss." },Array.Empty<string>()) {
			Why = "AoE damage and tankiness as needed.",
			Abilities = new string[10] { "Mana Manifestation: summons adds at an AoE", "Shockwave: knockback from the middle (pet cover can stop it)", "Dark II: frontal cone", "Forsaken Fount: spawns orbs that pulse AoEs periodically, larger orbs making bigger ones", "Gremlins (add): the red one applies physical vulnerability, the rest just attack", "Vodoriga (add): baited AoEs", "Bavarois (add): knocks back when killed and spawns nine puddles that raise fire resistance and lower lightning resistance", "Pudding (add): stack marker", "Flan (add): spread marker plus lots of AoEs", "Dahak (add): Tail Drive is a cone behind, Rotten Breath a cone in front" }
		},
		new CrucibleGuideFight("Drake Piece","Normal",new string[1] { "Drake Piece" },new int[3] { 50, 31, 48 },new string[2] { "Spawn Karlabos for Quelling Wave, then swap to Behemoth. Follow the Drake to the wall to avoid Burning Cyclone, and dispel Blaze Spikes with Quelling Wave. Kill the Barbmoles with Meteor and Parting Blow.", "When the Abbadon and Morphos spawn, kill the Morphos and then the Abbadon; if the Abbadon reaches the Morphos it eats them and gains regen. Another option is letting it eat them all and kiting until the regen falls off, but on standard mode you can just kill the Morphos quickly." },new string[1] { "Dispel" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Wavekin },
			Busters = new string[1] { "Mangling Fang" },
			Dispels = new string[1] { "Blaze Spikes" },
			OpenWith = BeastKin.Wavekin,
			TemperedFor = new string[1] { "Barbmole" },
			Why = "Good AoE for the initial adds, plus a dispel and Water damage (Karlabos's Quelling Wave) for later.",
			Abilities = new string[6] { "Burning Cyclone: jumps to a side then a frontal cone; spawns fireballs that do periodic circle AoEs, and when they stop one becomes a tornado that does a donut", "Blaze Spikes: dispellable; reflects damage when the boss is attacked", "Mangling Fang: tank buster", "Barbmole (add): Needles Out makes it reflect damage with a stacking bleed (cannot be dispelled); also Seeding Needles, a large circle AoE", "Abbadon (add): eats Morphos and gains regen stacks (no regen if the Morpho is low health when eaten)", "Morpho (add): applies stacks that confuse at 16; confuses you if killed normally, and must be eaten by the Abbadon" }
		},
		new CrucibleGuideFight("Durga Piece","Elite",new string[1] { "Durga" },new int[3] { 34, 5, 35 },new string[4] { "Start with Raptor and DPS the boss. Note which arm is not channelling during Electric Absorption: the Grounding Jolt safe spot is far from the boss in that arm's direction.", "Thermobaric Charge sends you corner to corner and Snarl cannot tank it: drop the charge in a corner and get knocked to the other (Shield Charge helps).", "Missile: stand still until the missiles lock in, then leave the line. Diffusion Ray: stand to the side or behind. When it casts Summon, kill the rooks, swapping to Opo-opo for Blunt damage.", "Watch your health for Atomic Ray, or dedicate a pet to sacrifice with a Ring of Sacrifice. You can also swap to Drake and use Smoldering Scales to cut the damage a lot. After that it is the same mechanics layered and sometimes faster until dead." },Array.Empty<string>()) {
			Busters = new string[1] { "Atomic Ray" },
			Why = "Plenty of damage, and Drake for Smoldering Scales.",
			Abilities = new string[7] { "Electric Absorption: tethers three pillars and absorbs energy into the hands", "Grounding Jolt: four AoEs from each hand; the hand that did not absorb does a smaller AoE; rotates before attacking from the second cast on", "Missile: line AoEs that track you and lock in when the lasers turn red", "Thermobaric Charge: baited very large knockback; cannot be stopped with pet cover", "Diffusion Ray: frontal cone", "Summon: four spinner-rooks, a damage check before the bar fills", "Atomic Ray: heavy raidwide; pet cover will not take it for you" }
		},
		new CrucibleGuideFight("Medusa Piece","Random",new string[1] { "Medusa" },new int[3] { 16, 32, 47 },new string[3] { "Start with Ice Golem for Soul Crush, then switch to Mantis. Burn the adds, but do not bait Petrifying Regard onto the lamias. When one lamia dies the other tries to raise it: interrupt with Soul Crush. Another lamia spawns after - interrupt and kill it too.", "Four cyclops spawn next. Bait a cone onto one to petrify it and kill it in one hit, then kill the others. If any are still up when the boss rotates Petrifying Regard, petrify and one-shot them again.", "Rippling and Constricting Evisceration: avoid the lines, stay out or in as appropriate, then swap positions for the second AoE. Then it repeats until dead." },new string[1] { "Interrupt" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Soulkin },
			OpenWith = BeastKin.Soulkin,
			Why = "A lot of damage and an interrupt through Ice Golem.",
			Abilities = new string[6] { "Summon: two lamias on the first cast, then one lamia and four cyclops on the second", "Petrifying Regard: tether; baited petrify cone that damage-buffs lamias and petrifies cyclops it hits; also rotating versions; being petrified by it kills you instantly", "Impassion: self vulnerability-down and damage buff; cannot be dispelled", "Rippling / Constricting Evisceration: two sets of lines that fire cones in the order they spawned; Rippling is circle then donut, Constricting is donut then circle", "Lamia (add): tries to revive dead lamias; otherwise basic circle AoEs", "Cyclops (add): casts circle AoEs covering the arena when spawned; dies instantly to any damage while petrified; casts line AoEs in front afterwards" }
		},
		new CrucibleGuideFight("Chimera Piece","Elite",new string[1] { "Chimera Piece" },new int[3] { 16, 32, 13 },new string[3] { "Grab Scouring Ash from Geshunpest then swap to Mantis. The attacks roughly follow an order, but be ready for all of them.", "Breaths pair with the roars: note which are cast and which head glows, and dodge. Stretch the Rushing Roar tether until it is purple at the edge, then dodge the breath.", "Toxic Tantrum poisons: cleanse it with Scouring Ash or have your pet take it. Cacophony spawns an orb - avoid it, but beware the roar and breath happening at the same time. Drop The Ram's Keeper at the wall and move away so it does not expand onto you. Then it repeats until dead." },new string[1] { "Cleanse" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Ashkin },
			Why = "A lot of damage plus a cleanse.",
