		new CrucibleGuideFight("Sphinx Piece","Normal",new string[1] { "Sphinx" },new int[3] { 16, 32, 1 },new string[3] { "The Banish pose is hard to tell apart, so watch it. Floating: stand on the side opposite the glowing wing. On the ground with front feet together: stay in for the donut. On the ground with feet apart: get away for the circle.", "Numeric Riddle: stand on a tile that matches a correct answer. Mnemonic Riddle follows: note the question, follow the beasts as they jump around, and interact with the mandragora the correct beast became. Then go back to blasting the boss.", "Lost Hope can make dodging tricky, but you can definitely kill it before that happens." },Array.Empty<string>()) {
