		new CrucibleGuideFight("Gigantis Piece","Normal",new string[1] { "Gigantis" },new int[3] { 31, 50, 47 },new string[4] { "Start with Ice Golem for Soul Crush, then swap to Gigantoad before pulling.", "Gigantic Rage: note the animation and dodge. It is hard to learn, so stand away at its sides and move the moment you see the telegraph until you are comfortable.", "When the boss spawns a slime, bait Smashing Stamp onto it. A crushed slime's element is absorbed and adds an effect after Gigantic Rage: a lightning club leaves a tower under you (stay in it), a fire club leaves an AoE under you (move). Do not hit a slime of the same element as the club, or it grows large instead of dying.", "With two slimes up, have the boss crush the one opposite to the club's element, interrupt the other, and blow that one up on the next Smashing Stamp. Tiny slimes fall to Shield Charge or Meteor. Kill any Cyclops adds you see, then resume killing the boss." },new string[1] { "Interrupt" }) {
			BorrowKins = new BeastKin[1] { BeastKin.Soulkin },
			Interrupts = new string[2] { "Rupture", "Camaraderie" },
