		new CrucibleGuideFight("Moogle Pieces","Random",new string[1] { "Moogle" },new int[3] { 50, 28, 47 },new string[2] { "Not much strategy: kill the moogles as fast as you can. The waves are on a timer and start even if you have not killed the previous ones.", "Wave 1: kill with AoE. Wave 2: stand at the wall without a moogle. Wave 3: focus down one pair, since its stacks ramp faster. Wave 4: avoid the exaflares and kill the adds. Wave 5: just kill them. Wave 6: step on the bubbles to pop them (and kill the Mugger before it takes your tokens)." },Array.Empty<string>()) {
			Why = "AoE and tankiness.",
			Abilities = new string[6] { "First wave: six Swordsmogs - just kill them", "Second wave: three Mogbreakers; large circle AoEs when they spawn", "Third wave: three Kinged Kupocasters and Kupocurers (two and one, or one and two); Curers cast Pom Flood, Casters Pom Flare, each applying a vulnerability of its element", "Fourth wave: three Kupocasters; exaflares that grow larger as they move", "Fifth wave: three Kupocurers; an AoE in a triangle connecting them", "Sixth wave: one Kinged Swordsmog, one Mogmugger and two Melomogs; the Mugger steals your tokens and leaves after a while, Melomogs spawn bubbles that heal and buff the Swordsmog, and the Swordsmog buffs itself and does raidwides" }
