		new CrucibleGuideFight("Behemoth Piece","Random",new string[1] { "Behemoth Piece" },new int[3] { 23, 28, 40 },new string[3] { "Very similar to any Behemoth in the game, with slight twists. The Energy Towers gain a ring when hit by a lightning puddle and two stacks from Lightning Barrage. Interact with them to release the energy; at three rings they detonate and stun you.", "Save at least one Meteor Impact rock for later and do not drop them too close together. Lightning Barrage: stand next to a tower to pass the debuff and step away once you see the circle under the tower. The sprite crosses do not charge the towers, but the puddles do.", "Nothing too spicy - it dies fairly quickly if you fight it." },Array.Empty<string>()) {
