	private static readonly CrucibleGuideBoard[] Boards=new CrucibleGuideBoard[5] { First, Second, Third, FirstMaster, SecondMaster };
	public static CrucibleGuideBoard? ForBoard(int board) {
		return Boards.FirstOrDefault((CrucibleGuideBoard b) => b.Board==board);
	}
	public static CrucibleGuideFight? FindFight(int board,string enemy) {
		if(string.IsNullOrWhiteSpace(enemy)) {
			return null;
		}
		return ForBoard(board)?.Fights.FirstOrDefault((CrucibleGuideFight fight) => fight.Match.Any((string fragment) => enemy.Contains(fragment,StringComparison.OrdinalIgnoreCase)));
	}
	public static bool LooksLikeEnemy(string text) {
		if(!string.IsNullOrWhiteSpace(text)&&!text.StartsWith("Enemy #",StringComparison.OrdinalIgnoreCase)&&!text.StartsWith("Move ",StringComparison.OrdinalIgnoreCase)&&!text.StartsWith("Shop #",StringComparison.OrdinalIgnoreCase)&&!text.StartsWith("Weakness",StringComparison.OrdinalIgnoreCase)) {
			return !text.Contains(':');
		}
		return false;
	}
	public static bool IsKnownEnemy(string text) {
		return Boards.Any((CrucibleGuideBoard b) => b.Fights.Any((CrucibleGuideFight f) => f.Match.Any((string m) => text.Contains(m,StringComparison.OrdinalIgnoreCase))));
	}
	public static string TeamKey(int board,CrucibleGuideFight fight) {
		return $"{board}:{fight.Name}";
	}
}
